"use client";
import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
type Role="super_admin"|"admin"|"user";
type UserRow={id:string;email:string;role:Role;status:string;isActive:boolean;invitedAt:string|null;lastSignInAt:string|null;invitedBy:string|null;invitationId:string|null;invitationStatus:string|null;canManage:boolean};
const labels:Record<Role,string>={super_admin:"Super Admin",admin:"Admin",user:"User"};

export function UserManagementPanel(){
  const[users,setUsers]=useState<UserRow[]>([]),[actorRole,setActorRole]=useState<Role>("user"),[roles,setRoles]=useState<("admin"|"user")[]>([]),[search,setSearch]=useState(""),[modal,setModal]=useState(false),[email,setEmail]=useState(""),[role,setRole]=useState<"admin"|"user">("user"),[message,setMessage]=useState(""),[error,setError]=useState(""),[pending,setPending]=useState(false),[setupUrl,setSetupUrl]=useState("");
  const load=useCallback(async()=>{const r=await fetch("/api/admin/users",{cache:"no-store"}),b=await r.json();if(r.ok){setUsers(b.users);setActorRole(b.actorRole);setRoles(b.allowedRoles);if(!b.allowedRoles.includes(role))setRole("user")}else setError(b.error??"Users could not be loaded.")},[role]);
  useEffect(()=>{void load()},[load]);
  const visible=useMemo(()=>users.filter(u=>u.email.includes(search.trim().toLowerCase())),[users,search]);
  async function invite(e:FormEvent){e.preventDefault();setPending(true);setError("");setMessage("");setSetupUrl("");const r=await fetch("/api/admin/users",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,role})}),b=await r.json();setPending(false);if(!r.ok){setError(b.error??"Invitation could not be sent.");return}setMessage(b.message);setModal(false);setEmail("");await load()}
  async function generateSetupLink(){setPending(true);setError("");setMessage("");setSetupUrl("");const r=await fetch("/api/admin/users/setup-link",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,role})}),b=await r.json();setPending(false);if(!r.ok){setError(b.error??"Secure setup link could not be generated.");return}setMessage(b.message);setSetupUrl(b.setupUrl);setModal(false);setEmail("");await load()}
  async function copySetupLink(){await navigator.clipboard.writeText(setupUrl);setMessage("Secure setup link copied. Share it only with the intended recipient.")}
  async function action(path:string,body?:unknown){setError("");setMessage("");setSetupUrl("");const r=await fetch(path,{method:"POST",headers:{"Content-Type":"application/json"},body:body===undefined?undefined:JSON.stringify(body)}),b=await r.json();if(!r.ok){setError(b.error??"Action could not be completed.");return}setMessage(b.message);if(b.setupUrl)setSetupUrl(b.setupUrl);await load()}
  return <section className="userManagement"><div className="userToolbar"><input aria-label="Search users" placeholder="Search users…" value={search} onChange={e=>setSearch(e.target.value)}/><button onClick={()=>{setError("");setMessage("");setSetupUrl("");setModal(true)}}>+ Add User</button></div>{message&&<div className="authSuccess" role="status">{message}</div>}{error&&<div className="authError" role="alert">{error}</div>}{setupUrl&&<div className="authSuccess setupLinkResult" role="status"><strong>Secure setup link</strong><input aria-label="Secure setup link" readOnly value={setupUrl}/><button type="button" onClick={copySetupLink}>Copy Setup Link</button><small>This link contains a sensitive, time-limited token. Share it only with the intended recipient.</small></div>}<div className="userTable"><div className="userTableHead"><span>Email</span><span>Role</span><span>Status</span><span>Invited / Last sign-in</span><span>Actions</span></div>{visible.map(u=><div className="userTableRow" key={u.id}><div><strong>{u.email}</strong><small>{u.invitedBy?`Invited by ${u.invitedBy}`:"Platform owner"}</small></div><span className={`roleBadge role-${u.role}`}>{labels[u.role]}</span><span className={`accountStatus ${u.status==="Active"?"active":""}`}>{u.status}</span><div><small>{u.invitedAt?`Invited ${new Date(u.invitedAt).toLocaleDateString()}`:"Existing account"}</small><small>{u.lastSignInAt?`Last sign-in ${new Date(u.lastSignInAt).toLocaleDateString()}`:"No sign-in yet"}</small></div><div className="userActions">{u.canManage&&u.invitationId&&u.invitationStatus==="pending"&&<button onClick={()=>action(`/api/admin/users/${u.invitationId}/resend`)}>Resend Invitation</button>}{actorRole==="super_admin"&&u.invitationId&&u.invitationStatus==="pending"&&<button onClick={()=>action(`/api/admin/users/${u.invitationId}/setup-link`)}>Generate Setup Link</button>}{u.canManage&&u.invitationStatus!=="pending"&&<button onClick={()=>action(`/api/admin/users/${u.id}/status`,{active:!u.isActive})}>{u.isActive?"Disable Account":"Enable Account"}</button>}</div></div>)}</div>{modal&&<div className="modalBackdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setModal(false)}}><form className="addUserModal" onSubmit={invite} role="dialog" aria-modal="true" aria-labelledby="add-user-title"><h2 id="add-user-title">Add User</h2><label>Email Address<input type="email" required autoFocus value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Role{actorRole==="super_admin"?<select value={role} onChange={e=>setRole(e.target.value as"admin"|"user")}>{roles.map(r=><option value={r} key={r}>{labels[r]}</option>)}</select>:<input value="User" readOnly/>}</label><div className="modalActions"><button type="button" className="secondary" onClick={()=>setModal(false)}>Cancel</button>{actorRole==="super_admin"&&<button type="button" className="secondary" disabled={pending||!email} onClick={()=>generateSetupLink()}>{pending?"Generating…":"Generate Setup Link"}</button>}<button disabled={pending}>{pending?"Sending…":"Send Invitation"}</button></div></form></div>}</section>;
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { getSupabasePublicConfig } from "../../../lib/supabase/config";
import { createServiceClient } from "../../../lib/supabase/service";
import {
  classifyInvitationDeliveryFailure,
  managementAudit,
  normalizedEmail,
  publicOrigin,
  safeProviderDiagnostic,
  sameOrigin,
  validEmail,
} from "../../../lib/user-management";

const successMessage = "We've sent password reset instructions to your email address.";
const failureMessage = "We couldn't send the reset email right now. Please try again.";
const rateLimitMessage = "Too many reset requests. Please wait a minute and try again.";
const resetAttempts = new Map<string, number>();
const RESET_COOLDOWN_MS = 60_000;

function response(message: string, status = 200) {
  return NextResponse.json({ message }, { status, headers: { "Cache-Control": "private, no-store", Pragma: "no-cache" } });
}

export async function POST(request: NextRequest) {
  if (!sameOrigin(request)) return response(successMessage);

  const body = (await request.json().catch(() => ({}))) as Record<string, unknown>;
  const email = normalizedEmail(body.email);
  if (!validEmail(email)) return response("Enter a valid email address.", 400);

  const clientAddress = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ?? "local";
  const rateLimitKey = `${clientAddress}:${email}`;
  const lastAttempt = resetAttempts.get(rateLimitKey) ?? 0;
  if (Date.now() - lastAttempt < RESET_COOLDOWN_MS) return response(rateLimitMessage, 429);
  resetAttempts.set(rateLimitKey, Date.now());

  const redirectTo = `${publicOrigin(request)}/auth/callback?next=${encodeURIComponent("/reset-password")}`;
  try {
    const { url, key } = getSupabasePublicConfig();
    const auth = createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } });
    const { error } = await auth.auth.resetPasswordForEmail(email, { redirectTo });
    if (error) {
      const diagnostic = safeProviderDiagnostic(error);
      console.warn("KDI_PASSWORD_RESET_DELIVERY", diagnostic);
      if (classifyInvitationDeliveryFailure(error) === "email_rate_limit") return response(rateLimitMessage, 429);
      return response(failureMessage, 503);
    }

    // Auditing must never turn an accepted provider delivery into a client-visible failure.
    try {
      const service = createServiceClient();
      const { data: profile } = await service.from("app_users").select("user_id,email").eq("email", email).maybeSingle();
      if (profile) await managementAudit(null, "password_reset_requested", { targetUserId: profile.user_id, targetEmail: profile.email });
    } catch (auditError) {
      console.warn("KDI_PASSWORD_RESET_AUDIT", { reason: "audit_failed" });
    }
    return response(successMessage);
  } catch (error) {
    console.warn("KDI_PASSWORD_RESET_DELIVERY", safeProviderDiagnostic(error));
    return response(failureMessage, 503);
  }
}

import { isLocalLibraryMediaConfigured } from "../../../../../../lib/library/local-preview";
import { isLibraryDevBypassEnabled } from "../../../../../../lib/library/dev-bypass";
import { fetchDevDriveMedia, mediaErrorResponse, mediaHeaders } from "../../../../../../media-service";
export const runtime = "nodejs"; export const dynamic = "force-dynamic";
export async function GET(request: Request, { params }: { params: Promise<{ assetId: string }> }) { if (!isLocalLibraryMediaConfigured()) return new Response("Not Found", { status: 404 }); try { const media = await fetchDevDriveMedia((await params).assetId, request.headers.get("range"), request.signal); if (media.record.extension.toLowerCase() === "pptx") return new Response("Preview unavailable for this format", { status: 415, headers: { "Cache-Control": "private, no-store" } }); return new Response(media.upstream.body, { status: media.upstream.status, headers: mediaHeaders(media.record, media.upstream, "inline") }); } catch (error) { return mediaErrorResponse(error, { operation: "preview" }); } }

import { fetchDevDriveThumbnail, mediaErrorResponse, thumbnailHeaders } from "../../../../../../media-service";
import { isLocalLibraryMediaConfigured } from "../../../../../../lib/library/local-preview";
import { isLibraryDevBypassEnabled } from "../../../../../../lib/library/dev-bypass";

export const dynamic = "force-dynamic";

export async function GET(request: Request, { params }: { params: Promise<{ assetId: string }> }) {
  if (!isLocalLibraryMediaConfigured()) return new Response("Not Found", { status: 404, headers: { "Cache-Control": "private, no-store" } });
  try {
    const result = await fetchDevDriveThumbnail((await params).assetId, request.signal, request.headers.get("if-none-match"));
    if (result.status === 304) return new Response(null, { status: 304, headers: { ETag: result.etag, "Cache-Control": "private, max-age=3600, stale-while-revalidate=86400" } });
    return new Response(new Uint8Array(result.bytes), { status: 200, headers: thumbnailHeaders(result.etag, result.contentType) });
  } catch (error) {
    return mediaErrorResponse(error, { operation: "thumbnail" });
  }
}

/**
 * The one canonical production search entry point.
 *
 * Every production search request terminates here. There is no version branching, no silent
 * fallback to an earlier engine, and no second parser: interpretation comes from the canonical
 * query interpreter and retrieval from executeCanonicalSearch. The developer library preview lives
 * behind its own explicitly non-production route and can never serve this endpoint.
 */
