      `\\b${verbs}\\s+(?:the\\s+)?(?:best\\s+)?(${numberWord})(?:\\s+(?!years?\\b|year-old\\b|grafts?\\b|seconds?\\b|minutes?\\b|percent\\b|RM\\b)[A-Za-z-]+){1,5}\\s+${media}\\b`,
      "gi",
