  &&(c.expectCount===undefined||count===c.expectCount)
  &&(!c.expectMedia||controlled.candidates.every((x:any)=>String(evidence.metadata[x.asset_id]?.mimeType??"").toUpperCase().startsWith(c.expectMedia!)))
