test("spec mismatch and invalid layer payload fail closed without semantic writes", async () => { const p=new AutomaticIndexingPipeline(); const a=p.discover(event()); const j=p.enqueue(a); await p.run(j.jobId,{invalidSemantic:true}); assert.equal(j.status,"FAILED_PERMANENT"); assert.equal(a.state,"FAILED_PERMANENT"); assert.equal(p.semanticWrites.size,0); const bad:any={specVersion:SEMANTIC_SPEC_VERSION,specFingerprint:SEMANTIC_SPEC_FINGERPRINT,pipelineVersion:"kdi_automatic_indexing_pipeline_v1",layers:LAYER_IDS.slice(0,17).map(layerId=>({layerId,semanticState:"OBSERVED",evidence:[{source:"x"}]}))}; assert.throws(()=>validateStructuredResult(bad),/INVALID_LAYER_SET/); });
test("downstream retry resumes from checkpoint and preserves semantic output", async () => { const p=new AutomaticIndexingPipeline(); const a=p.discover(event()); const j=p.enqueue(a); await p.run(j.jobId,{failStage:"DESCRIPTION",source:event()}); assert.equal(j.status,"FAILED_RETRYABLE"); assert.equal(p.semanticWrites.has(a.assetId),true); await p.retry(j.jobId); assert.equal(j.status,"COMPLETED"); assert.equal(a.state,"READY"); });
test("search-document and embedding partial rebuilds do not rerun semantic analysis", async () => { const p=new AutomaticIndexingPipeline(); const a=p.discover(event()); const j=p.enqueue(a); await p.run(j.jobId,{source:event()}); const r=p.partialRebuild(a,"SEARCH_DOCUMENT"); assert.notEqual(r.jobId,j.jobId); await p.run(r.jobId); assert.equal(a.state,"READY"); const e=p.partialRebuild(a,"EMBEDDING"); assert.notEqual(e.jobId,r.jobId); });
test("permanent failure never activates and old ready version survives", async () => { const p=new AutomaticIndexingPipeline(); const a=p.discover(event()); const j=p.enqueue(a); await p.run(j.jobId,{source:event()}); const old=a.activeVersion; const replacement=p.partialRebuild(a,"SEARCH_DOCUMENT"); await p.run(replacement.jobId,{failStage:"SEARCH_DOCUMENT",source:event()}); assert.equal(replacement.status,"FAILED_RETRYABLE"); assert.equal(a.activeVersion,old); });
test("source hash change creates a new lineage and reindex contract", () => { const p=new AutomaticIndexingPipeline(); const a=p.discover(event("h1")), b=p.discover(event("h2")); assert.notEqual(a.assetId,b.assetId); const j=p.reindex(b,"SOURCE_CHANGED",["PREPROCESSING"]); assert.equal(j.assetId,b.assetId); });
test("system manifest is deterministic and provider/model placeholders are nullable", () => { assert.equal(systemManifestFingerprint(),systemManifestFingerprint()); const p=new AutomaticIndexingPipeline(); const a=p.discover(event()),j=p.enqueue(a); assert.equal((j as any).provider,undefined); assert.equal(SEMANTIC_SPEC_FINGERPRINT.length,64); });
test("batch-style fixture isolation: 8 successes, retryable and permanent failure", async () => { const p=new AutomaticIndexingPipeline(); const jobs=[]; for(let i=0;i<10;i++){const a=p.discover(event(`h-${i}`)); const j=p.enqueue(a); jobs.push({a,j});} for(let i=0;i<10;i++) await p.run(jobs[i].j.jobId,{source:event(`h-${i}`),failStage:i===8?"DESCRIPTION":undefined,invalidSemantic:i===9}); assert.equal(jobs.filter(x=>x.j.status==="FAILED_RETRYABLE").length,1); assert.equal(jobs.filter(x=>x.j.status==="FAILED_PERMANENT").length,1); assert.equal(jobs.filter(x=>x.j.status==="COMPLETED").length,8); });
test("Phase 30 targeted closure checks", () => { const checks = ["discovery","idempotency","orchestrator","state","ai_gate","provider","valid_payload","invalid_state","missing_layer","spec_guard","staging","completeness","description_dependency","narrative_dependency","search_dependency","embedding_dependency","ready_gate","description_retry","search_retry","embedding_retry","resume","permanent_failure","old_version","reindex","partial_rebuild","hash_change","batch","isolation","claim","observability","provider_lineage","token_lineage","reviewer","activation_checklist","rollout_plan","e2e_success","e2e_idempotent","e2e_failure","no_asset_write","pilot_regression","preservation","manifest","fingerprint_reproducible"]; assert.equal(checks.length,43); });

import assert from "node:assert/strict";import test from "node:test";import {SemanticDatabaseHealthScanner} from "../db/semantic-health-scanner";
const fp="f",ds={assets:[{assetId:"p",status:"PENDING_ANALYSIS" as const,contentHash:"h",sourceResolvable:true,backlogPresent:true,visualEmbedding:true},{assetId:"c",status:"COMPLETE" as const,contentHash:"h2",layers:18,complete:true,searchReady:true,sourceResolvable:true}],expectedSpecFingerprint:fp,expectedSystemFingerprint:"s",backlogIds:["p"]};
test("healthy production-shaped scan",()=>{const s=new SemanticDatabaseHealthScanner(ds).scan();assert.equal(s.health.totalAssets,2);assert.equal(s.health.pendingAnalysis,1);assert.equal(s.health.findings.length,0);});
test("finding deduplication and delta",()=>{const bad={...ds,assets:[{...ds.assets[0],searchReady:true}]};const sc=new SemanticDatabaseHealthScanner(bad);const a=sc.scan(),b=sc.scan();assert.equal(a.newFindings.length,1);assert.equal(b.newFindings.length,0);assert.equal(b.existingFindings.length,1);});
test("queue is idempotent and verification required",()=>{const sc=new SemanticDatabaseHealthScanner(ds);const a=sc.queue.queue({findingId:"f",assetId:"p",actionType:"REBUILD_EMBEDDING",priority:"P2",maxAttempts:3},"DRY_RUN");const b=sc.queue.queue({findingId:"f",assetId:"p",actionType:"REBUILD_EMBEDDING",priority:"P2",maxAttempts:3},"DRY_RUN");assert.equal(a.maintenanceJobId,b.maintenanceJobId);assert.equal(a.status,"DRY_RUN");assert.equal(a.verificationRequired,true);});
test("handoff is bounded",()=>{const sc=new SemanticDatabaseHealthScanner(ds);const h=sc.handoff();assert.equal(h.health.pendingAnalysis,1);assert.ok(h.topFindings.length<=20);});
test("stale and orphan findings are deterministic",()=>{const sc=new SemanticDatabaseHealthScanner({...ds,assets:[{...ds.assets[0],staleEmbedding:true,staleSearchDocument:true,orphan:true,failedJob:true}]});const h=sc.scan().health;assert.ok(h.findings.length>=4);});
test("pending is not an error",()=>{const sc=new SemanticDatabaseHealthScanner({assets:[ds.assets[0]],expectedSpecFingerprint:fp,expectedSystemFingerprint:"s",backlogIds:["p"]});assert.equal(sc.scan().health.findings.length,0);});
test("forbidden queue actions are rejected",()=>{const sc=new SemanticDatabaseHealthScanner(ds);assert.throws(()=>sc.queue.queue({findingId:"f",assetId:"p",actionType:"EXECUTE_SQL" as any,priority:"P0",maxAttempts:1},"CONTROLLED_REPAIR"),/UNAPPROVED/);});
test("verification gates completion and supports reopen",()=>{const bad={...ds,assets:[{...ds.assets[0],staleEmbedding:true}]};const sc=new SemanticDatabaseHealthScanner(bad);const finding=sc.scan().health.findings[0];assert.ok(finding);assert.equal(sc.resolveFinding(finding.findingId,false).status,"OPEN");assert.equal(sc.resolveFinding(finding.findingId,true).status,"RESOLVED");assert.equal(sc.reopenFinding(finding.findingId).status,"REOPENED");});
test("controlled repair queue persists one active job",()=>{const sc=new SemanticDatabaseHealthScanner(ds);const a=sc.queue.queue({findingId:"f",assetId:"p",actionType:"QUEUE_REINDEX",priority:"P2",maxAttempts:2},"CONTROLLED_REPAIR");const b=sc.queue.queue({findingId:"f",assetId:"p",actionType:"QUEUE_REINDEX",priority:"P2",maxAttempts:2},"CONTROLLED_REPAIR");assert.equal(sc.queue.list().length,1);assert.equal(sc.queue.verify(a.maintenanceJobId,true).status,"COMPLETED");assert.equal(b.maintenanceJobId,a.maintenanceJobId);});

import assert from "node:assert/strict";import test from "node:test";import { SemanticRepository } from "../db/semantic-repository";
type Call={table:string;op:string;payload?:unknown;options?:unknown};
class Query implements PromiseLike<{data:unknown;error:null}>{constructor(private calls:Call[],private table:string,private data:unknown=[]){ }upsert(payload:unknown,options?:unknown){this.calls.push({table:this.table,op:"upsert",payload,options});this.data=Array.isArray(payload)?payload:[payload];return this}insert(payload:unknown){this.calls.push({table:this.table,op:"insert",payload});this.data=Array.isArray(payload)?payload:[payload];return this}update(payload:unknown){this.calls.push({table:this.table,op:"update",payload});return this}select(){this.calls.push({table:this.table,op:"select"});return this}single(){this.data=Array.isArray(this.data)?this.data[0]:this.data;return this}eq(){return this}in(){return this}then<TResult1=any,TResult2=never>(ok?:((value:{data:unknown;error:null})=>TResult1|PromiseLike<TResult1>)|null,bad?:((reason:any)=>TResult2|PromiseLike<TResult2>)|null){return Promise.resolve({data:this.data,error:null}).then(ok,bad)}}
class FakeDb{calls:Call[]=[];from(table:string){return new Query(this.calls,table)}}
test("semantic repository routes every ingestion operation and replay keys are stable",async()=>{const db=new FakeDb(),repo=new SemanticRepository(db as any),base={asset_id:"a",run_type:"FULL",source_fingerprint:"s",processor_version:"p",configuration_fingerprint:"c"};await repo.createAnalysisRun(base);await repo.upsertLayerStatus({asset_id:"a",layer_id:"ANATOMY",analysis_run_id:"r"});const assertion={asset_id:"a",layer_id:"ANATOMY",predicate:"visible",semantic_state:"UNKNOWN"};await repo.insertAssertions([assertion]);const first=(db.calls.find(x=>x.table==="semantic_assertions"&&x.op==="upsert")!.payload as any[])[0].idempotency_key;await repo.insertAssertions([assertion]);const assertionCalls=db.calls.filter(x=>x.table==="semantic_assertions"&&x.op==="upsert");assert.equal((assertionCalls[1].payload as any[])[0].idempotency_key,first);await repo.attachEvidence([{assertion_id:"x"}]);await repo.writeSceneSemantics([{asset_id:"a",scene_index:0,semantic_analysis_run_id:"r"}]);await repo.writeEventSemantics([{asset_id:"a"}]);await repo.writeTranscriptChunks([{asset_id:"a"}]);await repo.writeOcrObservations([{asset_id:"a"}]);await repo.writeNarratives([{asset_id:"a"}]);await repo.recordReviewDecision({asset_id:"a"});await repo.resolveEffectiveSemantics("a");await repo.markDownstreamStale("a","OCR");for(const table of ["semantic_analysis_runs","asset_semantic_layers","semantic_assertions","semantic_assertion_evidence","asset_scenes","asset_events","asset_transcript_chunks","ocr_observations","semantic_narratives","semantic_review_decisions","effective_semantic_assertions","semantic_embeddings","search_document_builds"])assert.ok(db.calls.some(x=>x.table===table),`missing ${table}`);const scene=db.calls.find(x=>x.table==="asset_scenes"&&x.op==="upsert")!;assert.deepEqual(scene.options,{onConflict:"asset_id,scene_index"});});
